"""Bind original Section-end ports without splitting editable Street sources.

The editable mesh contains original source vertices and edges only. Separate
private tables address inclusive control ranges and original endpoint IDs.
No curve coefficients, samples, stations or surface coordinates are serialized.
"""
from dataclasses import dataclass
import math

from .curved_junction_bindings import _mesh


@dataclass(frozen=True)
class PortBindings:
    sources: object
    spans: object
    ports: object
    street_vertices: dict
    section_edges: dict
    junction_ranges: tuple


def dimension_transitions(plan, compiled, declarations, label):
    """Bind prepared tapers to original spans in a separate private table."""
    rows = []
    for declaration in declarations:
        matches = [(i, s) for i, s in enumerate(plan.spans) if s.street_id == declaration.street_id
                   and (declaration.before_section, declaration.after_section) in tuple(zip(s.section_ids, s.section_ids[1:]))]
        if len(matches) != 1:
            raise ValueError('A dimensional declaration must belong inside one original span')
        index, span = matches[0]
        edge_start = compiled.spans.attributes['st_ps_edge_start'].data[index].value
        before, after = (compiled.section_edges[sec] for sec in (declaration.before_section, declaration.after_section))
        if before[-1]+1 != after[0]:
            raise ValueError('A dimensional declaration lost its original Section seam')
        kinds = {'SymLane': 0, 'SideLane': 1, 'Intersection': 2, 'AuthoredTransition': 3}
        if declaration.source_kind not in kinds:
            raise ValueError('Unsupported original dimensional item kind')
        rows.append(dict(id=len(rows), span=index, street_id=span.street_id,
            vertex=after[0]-edge_start, before_section=declaration.before_section, after_section=declaration.after_section,
            source_kind=kinds[declaration.source_kind], source_id=declaration.source_id,
            minimum_half=declaration.minimum_half_length, maximum_slope=declaration.maximum_edge_slope))
    keys=('id','span','street_id','vertex','before_section','after_section','source_kind','source_id','minimum_half','maximum_slope')
    return _mesh(label+' private dimensional seams', [(0.,0.,0.)]*len(rows), [], [
        ('st_cd_'+key, 'FLOAT' if key in ('minimum_half','maximum_slope') else 'INT', 'POINT', [r[key] for r in rows]) for key in keys])


def network_tables(plan, network, compiled, approaches, label, *, allow_unresolved=False, join_radius=.5, dimensions=None, logical_clusters=False, shared_logical=False):
    """Private once-owned span routes; no source or solved geometry changes."""
    if tuple(r.span for r in network.routes)!=plan.spans:
        raise ValueError('Network routes must cover the exact prepared original spans')
    if network.unresolved and not allow_unresolved:
        raise ValueError('Unselected original connections remain; declare partial qualification explicitly')
    if not math.isfinite(join_radius) or join_radius<=0:
        raise ValueError('A compound joining radius must be positive and finite')
    port_index={p.endpoint:i for i,p in enumerate(p for s in plan.sites for p in s.ports)}
    span_index={s.identity:i for i,s in enumerate(plan.spans)}
    site_index={s.junction_id:i for i,s in enumerate(plan.sites)}
    roles={'CORRIDOR':1,'APPROACH':2,'CATEGORY_APPROACH':2,'SELECTION_APPROACH':2,'COMPOUND':3,'LOGICAL_CLUSTER':3,'REMOTE_CONNECTION':4}
    role_values=[0]*len(port_index);corridors=[];external=[];compounds=[]
    for route in network.routes:
        ports=tuple(p for p in (route.start_port,route.end_port) if p is not None)
        for port in ports:role_values[port_index[port.endpoint]]=roles[route.kind]
        span=route.span;common=dict(street_id=span.street_id,span_index=span_index[span.identity])
        if route.kind=='CORRIDOR':
            corridors.append(dict(**common,start_index=port_index[route.start_port.endpoint],end_index=port_index[route.end_port.endpoint]))
        elif route.kind=='APPROACH':
            external.append(dict(**common,start_index=port_index[ports[0].endpoint],end_role=1,owner_id=-1,next_section_id=-1))
        elif route.kind=='SELECTION_APPROACH':
            far=span.end if route.start_port is not None else span.start
            plan.selection_boundary(far.endpoint)
            external.append(dict(**common,start_index=port_index[ports[0].endpoint],end_role=6,
                                 owner_id=far.endpoint.section_id,next_section_id=-1))
        elif route.kind=='CATEGORY_APPROACH':
            far = span.end if route.start_port is not None else span.start
            boundary = plan.category_boundary(far.endpoint)
            peer = next(e for e in boundary.endpoints if e != far.endpoint)
            # Role 4 is an explicit continuation to another original Section,
            # not a free endpoint or an invented junction identity.
            cross = boundary.source_kind == 'OriginalStreetSeam'
            external.append(dict(**common,start_index=port_index[ports[0].endpoint],end_role=5 if cross else 4,
                                 owner_id=boundary.source_id if cross else span.street_id,next_section_id=peer.section_id))
    for item in network.compounds:
        compounds.append(dict(site_a=site_index[item.site_ids[0]],site_b=site_index[item.site_ids[1]],
                              span_index=span_index[item.span_identity],join_radius=join_radius))
    def table(name,prefix,rows,schema):
        return _mesh(label+' private '+name,[(0.,0.,0.)]*len(rows),[],[
            (prefix+key,kind,'POINT',[r[key] for r in rows]) for key,kind in schema])
    def ints(*keys):return [(key,'INT') for key in keys]
    incidences=approaches.copy();incidences.name=label+' private network incidences'
    incidences.attributes.new('st_cj_span_role','INT','POINT').data.foreach_set('value',role_values)
    sites=[dict(junction_id=jid,range_start=start,range_count=count) for jid,start,count in compiled.junction_ranges]
    result = dict(Sources=compiled.sources,Mapping=compiled.spans,Approaches=incidences,
        Junctions=table('sites','st_cj_',sites,ints('junction_id','range_start','range_count')),
        Corridors=table('corridors','st_cs_',corridors,ints('street_id','span_index','start_index','end_index')),
        **{'External Approaches':table('external','st_ca_',external,ints('street_id','span_index','start_index','end_role','owner_id','next_section_id')),
           'Compounds':table('compounds','st_cp_',compounds,ints('site_a','site_b','span_index')+[('join_radius','FLOAT')])})
    if dimensions is not None:
        selected = {d.value for d in dimensions.attributes['st_cd_span'].data}
        result['Corridors'].attributes.new('st_cs_dimensioned','INT','POINT').data.foreach_set(
            'value', [int(row['span_index'] in selected) for row in corridors])
        result['Transitions'] = dimensions
    if logical_clusters or network.logical_clusters:
        from .curved_logical_cluster_bindings import network_tables as logical_tables
        result.update(logical_tables(plan,compiled,network.logical_clusters,label,join_radius,shared_logical=shared_logical))
    return result


def surface_approaches(plan, compiled, designs, label, *, retain_unresolved=False):
    """Attach declared profiles/radii to the original incidence rows.

    The returned table remains private metadata. Mapping in the physical patch
    interface is the compiled Spans table; Sources remains the complete mesh.
    """
    ports=[port for site in plan.sites for port in site.ports]
    designs=tuple(designs)
    if len(designs)!=len(ports) or len(compiled.ports.vertices)!=len(ports):
        raise ValueError('Every original port needs exactly one surface design')
    rows=[]
    for port,design in zip(ports,designs):
        end=port.endpoint
        if (design.junction_id,design.street_id,design.section_id,design.end)!=(port.junction_id,end.street_id,end.section_id,end.end):
            raise ValueError('Surface design order differs from original Section-end ownership')
        rejected = bool(getattr(design, 'profile_error', None))
        if rejected and (not retain_unresolved or design.half_profile is not None):
            raise ValueError('An unresolved profile needs explicit rejection support and no substitute profile')
        if (not math.isfinite(design.radius) or design.radius<=0 or
            not math.isfinite(design.rise) or design.rise<0 or
            not math.isfinite(design.datum) or (not rejected and design.half_profile not in (-1,0,1))):
            raise ValueError('Invalid original port radius/profile declaration')
        bid=getattr(design,'bundle_id',-1)
        if (type(bid) is not int or bid < -1 or (rejected and bid < 0) or
                (bid >= 0 and design.half_profile == 0)):
            raise ValueError('A longitudinal Bundle port needs an explicit half-profile and integer owner')
        # 2 is deliberately outside the profile enumeration {-1, 0, 1}.
        # No full/half crown is invented for this rejected incidence. The
        # native source reader must reject it before any surface is published.
        rows.append(dict(radius=design.radius,rise=design.rise,datum=design.datum,
                         half=2 if rejected else design.half_profile,bundle_id=bid))
    result=compiled.ports.copy();result.name=label+' private surface incidences'
    order=[i for site in plan.sites for i in range(len(site.ports))]
    for key,values,kind in (
        ('order',order,'INT'),
        *((key,[row[key] for row in rows],'INT' if key in ('half','bundle_id') else 'FLOAT') for key in ('radius','rise','datum','half','bundle_id')),
        *((key,[item.value for item in compiled.ports.attributes['st_pp_'+original].data],'INT')
          for key,original in (('street_id','street_id'),('section_id','section_id'),('junction_id','junction_id'),
                              ('connector_id','connector_id'),('reverse','reverse'),('span_index','span'))),
    ):
        attr=result.attributes.new('st_cj_'+key,kind,'POINT');attr.data.foreach_set('value',values)
    if any(getattr(d, 'profile_error', None) for d in designs):
        attr=result.attributes.new('st_cj_profile_error','BOOLEAN','POINT')
        attr.data.foreach_set('value',[bool(getattr(d, 'profile_error', None)) for d in designs])
    return result


def compile(snapshot, plan, label, *, origin=(0., 0., 0.), endpoint_ownership=False):
    if len(origin) != 3 or not all(math.isfinite(v) for v in origin):
        raise ValueError('A port binding origin needs three finite coordinates')
    vertices, edges = [], []
    widths, offsets, street_ids, section_ids, feature_groups = [], [], [], [], []
    street_vertices, section_edges, source_ranges = {}, {}, {}
    if not plan.spans or len(set(plan.source_streets)) != len(plan.source_streets):
        raise ValueError('Port bindings need a nonempty prepared source plan')
    for sid in plan.source_streets:
        source = snapshot.streets[sid]
        if not plan.source_supported(source):
            raise ValueError('Port binding source is unsupported')
        sections = [s for s in source['items'] if s['kind'] == 'Section']
        scope=next((s for s in plan.section_scopes if s.street_id==sid),None)
        groups=dict(zip(scope.section_ids,scope.curve_groups)) if scope else {}
        begin, edge_begin = len(vertices), len(edges)
        previous = None
        expected = tuple(s['id'] for s in sections)
        actual = tuple(sec for span in plan.spans if span.street_id == sid for sec in span.section_ids)
        if expected != actual:
            raise ValueError('Port plan no longer covers the original Section order')
        for section in sections:
            points = [tuple(p)+(0.,)*(3-len(p)) for p in section['points']]
            if len(points) < 2 or any(len(p) != 3 or not all(math.isfinite(v) for v in p) for p in points):
                raise ValueError('Original controls must be finite 2D or 3D points')
            if previous is not None and math.dist(previous, points[0]) > 1e-5:
                raise ValueError('Consecutive original Sections are disconnected')
            start = len(vertices) if previous is None else len(vertices)-1
            vertices.extend(tuple(p[k]-origin[k] for k in range(3)) for p in (points if previous is None else points[1:]))
            first_edge = len(edges)
            for i in range(len(points)-1):
                edges.append((start+i, start+i+1))
                widths.append(float(section['width'])); offsets.append(float(section['offset'] or 0.))
                street_ids.append(sid); section_ids.append(section['id'])
                feature_groups.append(groups.get(section['id'],0))
            if section['id'] in section_edges:
                raise ValueError('An original Section has multiple editable owners')
            section_edges[section['id']] = tuple(range(first_edge, len(edges)))
            previous = points[-1]
        street_vertices[sid] = tuple(range(begin, len(vertices)))
        source_ranges[sid] = begin, edge_begin, len(vertices)-begin
    span_rows, span_indices = [], {}
    for span in plan.spans:
        begin, edge_begin, count = source_ranges[span.street_id]
        if count != span.source_control_count or not 0 <= span.first_control < span.last_control < count:
            raise ValueError('Original control topology changed; rebuild the port plan')
        # Count equality alone would miss moving a control from one Section to
        # another. Bind the actual first/last original Section edge ranges too.
        expected_first = section_edges[span.section_ids[0]][0]-edge_begin
        expected_last = section_edges[span.section_ids[-1]][-1]-edge_begin+1
        if (span.first_control, span.last_control) != (expected_first, expected_last):
            raise ValueError('Original Section seam changed; rebuild the port plan')
        if span.identity in span_indices:
            raise ValueError('Repeated original span identity')
        span_indices[span.identity] = len(span_rows)
        span_rows.append(dict(start=begin, edge_start=edge_begin, count=count,
            first=span.first_control, last=span.last_control, street_id=span.street_id,
            first_section=span.section_ids[0], last_section=span.section_ids[-1]))
    port_rows, junction_ranges = [], []
    kinds = {'PHYSICAL': 0, 'THROUGH': 1, 'ATTACHMENT': 2, 'SEAM': 3, 'AGGREGATE': 4}
    for site in plan.sites:
        begin = len(port_rows)
        for port in site.ports:
            span = plan.span_for(port)
            port_rows.append(dict(span=span_indices[span.identity], reverse=port.endpoint.end,
                street_id=port.endpoint.street_id, section_id=port.endpoint.section_id,
                junction_id=port.junction_id, connector_id=-1 if port.connector_id is None else port.connector_id,
                kind=kinds[port.source_kind]))
        junction_ranges.append((site.junction_id, begin, len(port_rows)-begin))
    seam_peers = {}
    for site in plan.sites:
        if not any(p.source_kind == 'SEAM' for p in site.ports):continue
        if len(site.ports) != 2 or any(p.source_kind != 'SEAM' or p.connector_id is not None for p in site.ports):
            raise ValueError('Seam binding needs two original incidences without invented Connectors')
        for own, peer in (site.ports, site.ports[::-1]):
            span = plan.span_for(own); partner = plan.span_for(peer)
            end = own.endpoint.end
            if (span.first_control if end == 0 else span.last_control) != (0 if end == 0 else span.source_control_count-1):
                raise ValueError('A seam must belong to the complete original Street terminal')
            key = own.endpoint.street_id, end
            if key in seam_peers:raise ValueError('Original Street terminal has multiple seam peers')
            seam_peers[key] = span_indices[partner.identity], peer.endpoint.end, site.junction_id
    seam_keys = tuple('seam_'+side+'_'+key for side in ('start','end') for key in ('span','end','id'))
    if seam_peers:
        for row in span_rows:
            for end, side in enumerate(('start','end')):
                record = seam_peers.get((row['street_id'],end),(-1,-1,-1))
                row.update(zip(('seam_'+side+'_'+key for key in ('span','end','id')),record))
    # Cross-feature declarations retain both original endpoint identities but
    # do not request a shared road tangent or a road-to-road seam surface.
    boundaries = {end:boundary for boundary in plan.category_connections for end in boundary.endpoints}
    category_keys = tuple('category_'+side+'_'+key for side in ('start','end')
                          for key in ('id','street','section','end'))
    if boundaries:
        for span, row in zip(plan.spans, span_rows):
            for own, side in ((span.start.endpoint,'start'),(span.end.endpoint,'end')):
                boundary = boundaries.get(own)
                record = (-1,-1,-1,-1)
                if boundary is not None:
                    peer = next(e for e in boundary.endpoints if e != own)
                    record = (boundary.source_id,peer.street_id,peer.section_id,peer.end)
                row.update(zip(('category_'+side+'_'+key for key in ('id','street','section','end')),record))
    def table(name, prefix, rows, keys):
        return _mesh(label+' '+name, [(0., 0., 0.)]*len(rows), [], [
            (prefix+key, 'INT', 'POINT', [r[key] for r in rows]) for key in keys])
    endpoint_keys=()
    if endpoint_ownership:
        endpoint_keys=('start_role','end_role')
        for span,row in zip(plan.spans,span_rows):
            for end,side in ((span.start,'start'),(span.end,'end')):
                role=1 if end.owner_kind=='FREE' else 0
                if end.owner_kind=='CATEGORY_BOUNDARY':
                    role=5 if plan.category_boundary(end.endpoint).source_kind=='OriginalStreetSeam' else 4
                if end.owner_kind=='SELECTION_BOUNDARY':role=6
                row[side+'_role']=role
    sources = _mesh(label+' original Streets', vertices, edges, [
        ('st_width', 'FLOAT', 'EDGE', widths), ('st_offset', 'FLOAT', 'EDGE', offsets),
        ('st_street_id', 'INT', 'EDGE', street_ids), ('st_section_id', 'INT', 'EDGE', section_ids),
        ('_ps_feature_group', 'INT', 'EDGE', feature_groups)])
    spans = table('private spans', 'st_ps_', span_rows,
        ('start','edge_start','count','first','last','street_id','first_section','last_section')
        +(seam_keys if seam_peers else ())+(category_keys if boundaries else ())+endpoint_keys)
    if plan.selection_boundaries:
        if not endpoint_ownership:raise ValueError('Selection trims require explicit endpoint roles')
        for side in ('start','end'):
            trims=[plan.selection_boundary(getattr(span,side).endpoint).trim_m
                   if getattr(span,side).owner_kind=='SELECTION_BOUNDARY' else 0. for span in plan.spans]
            spans.attributes.new('st_ps_'+side+'_clip','FLOAT','POINT').data.foreach_set('value',trims)
        # Interior cuts retain reciprocal original span references. Mapping
        # rows keep their order when provider scopes rebase source indices.
        endpoints={end.endpoint:i for i,span in enumerate(plan.spans) for end in (span.start,span.end)}
        peers={row.endpoint:plan.selection_peer(row.endpoint) for row in plan.selection_boundaries}
        if any(peer is not None for peer in peers.values()):
            for side in ('start','end'):
                indices=[endpoints[peers[getattr(span,side).endpoint]]
                         if peers.get(getattr(span,side).endpoint) is not None else -1 for span in plan.spans]
                spans.attributes.new('st_ps_'+side+'_clip_peer','INT','POINT').data.foreach_set('value',indices)
    return PortBindings(sources, spans,
        table('private ports', 'st_pp_', port_rows,
        ('span','reverse','street_id','section_id','junction_id','connector_id','kind')),
        street_vertices, section_edges, tuple(junction_ranges))
